import{_ as c,C as r,o as l,c as h,j as e,a as d,E as o,a5 as n}from"./chunks/framework.CyyS6Zdm.js";const g=JSON.parse('{"title":"数值动画","description":"","frontmatter":{},"headers":[],"relativePath":"components/number-animation.md","filePath":"components/number-animation.md","lastUpdated":1787173379000}'),s={name:"components/number-animation.md"},b={id:"数值动画",tabindex:"-1"};function u(m,t,p,x,f,q){const i=r("Badge"),a=r("XhDemo");return l(),h("div",null,[e("h1",b,[t[0]||(t[0]=d("数值动画 ",-1)),o(i,{type:"info",text:"number-animation"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#数值动画","aria-label":'Permalink to "数值动画 <Badge type="info" text="number-animation" />"'},"​",-1))]),t[3]||(t[3]=n('<p>数字从一个值滚动到另一个值。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>仪表盘上的关键指标首次出现时，用滚动强调它在变化。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>数值频繁变化：每次都滚一遍，用户永远读不到稳定值。</li><li>是精确的金额或编号，用户要读取而不是感知趋势。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>precision</code> 小数位、<code>separator</code> 千位分隔。</li><li><code>easing</code> 与 <code>duration</code> 决定滚动的节奏。</li><li><code>live</code> 决定读屏播报方式——通常应该只播报终值。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>挂载即从 from 走到 to，三个尺寸档只改字号；不写 size 就跟着上下文的字号走</p>',10)),o(a,{src:"number-animation/01-basic"}),t[4]||(t[4]=e("h3",{id:"小数位与千位分隔",tabindex:"-1"},[d("小数位与千位分隔 "),e("a",{class:"header-anchor",href:"#小数位与千位分隔","aria-label":'Permalink to "小数位与千位分隔"'},"​")],-1)),t[5]||(t[5]=e("p",null,"precision 定小数位，separator 定分隔符；不给分隔符就不分隔，插什么符号是地区习惯",-1)),o(a,{src:"number-animation/02-format"}),t[6]||(t[6]=e("h3",{id:"缓动与时长",tabindex:"-1"},[d("缓动与时长 "),e("a",{class:"header-anchor",href:"#缓动与时长","aria-label":'Permalink to "缓动与时长"'},"​")],-1)),t[7]||(t[7]=e("p",null,"duration 定跑多久，easing 定快慢怎么分配；同一段距离四档并排跑，差别一眼可见",-1)),o(a,{src:"number-animation/03-easing"}),t[8]||(t[8]=e("h3",{id:"跟着数据走",tabindex:"-1"},[d("跟着数据走 "),e("a",{class:"header-anchor",href:"#跟着数据走","aria-label":'Permalink to "跟着数据走"'},"​")],-1)),t[9]||(t[9]=e("p",null,"改 to 就从当前数字接着走向新终点，跑完停下之后再改也照样重新跑；active 翻假即停在当前值",-1)),o(a,{src:"number-animation/04-follow-data"}),t[10]||(t[10]=n('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-number-animation&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhNumberAnimation</code></td></tr><tr><td>状态机</td><td><code>numberAnimationMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/number-animation.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;number-animation&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>from</code></td><td><code>number</code></td><td></td><td>起点，缺省 0。改写它会把显示值当场落到新起点，并从那里重跑这一轮。</td></tr><tr><td><code>to</code></td><td><code>number</code></td><td></td><td>终点，缺省 0。改写它从当前显示值接着走向新终点，不跳回起点。</td></tr><tr><td><code>duration</code></td><td><code>number</code></td><td></td><td>时长毫秒，缺省 1000；&lt;=0 即一步到位。</td></tr><tr><td><code>easing</code></td><td><code>NumberAnimationEasing</code></td><td></td><td>缓动：linear / ease-in / ease-out / ease-in-out，缺省 linear。</td></tr><tr><td><code>precision</code></td><td><code>number</code></td><td></td><td>小数位，缺省 0。夹进 [0, 20]。</td></tr><tr><td><code>separator</code></td><td><code>string</code></td><td></td><td>千位分隔符，缺省不分隔。</td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td></td><td>是否在跑，缺省 true。翻假即停在当前值，翻真从当前值继续走向终点。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，只落成 root 的 data-size。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，只落成 root 的 data-tone。</td></tr><tr><td><code>live</code></td><td><code>NumberAnimationLive</code></td><td></td><td>读屏播报档位，缺省 off。</td></tr><tr><td><code>onFinish</code></td><td><code>(details: NumberAnimationFinishDetails) =&gt; void</code></td><td></td><td>走到终点时通知一次。中途被停掉不通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>finish</code></td><td><code>NumberAnimationFinishDetails</code></td><td>走到终点；detail 为 <code>{ value: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhNumberAnimation</code></td><td><code>default</code></td><td><code>NumberAnimationSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.STOP</code> · <code>RUN.SYNC</code> · <code>FRAME</code></p><p><strong>判据</strong>：<code>isSettled</code> · <code>isActive</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>NumberAnimationPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前数值（未格式化）。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>当前数值按 precision 与 separator 铺好的文本，也就是根里该显示的字。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td>是否还在跑。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#status" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/number-animation.css</code> 按部件选择：<code>[data-scope=&quot;number-animation&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-number-animation-fg</code> · <code>--xh-number-animation-font-size</code></p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./statistic">统计数值</a>的值位。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>时长控制在一秒以内，再长就成了等待。</li><li>读屏只播报终值，别把每一帧都念出来。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>给实时刷新的数字加滚动动画。</li><li>系统开启减弱动效时仍然滚动。</li></ul>',43))])}const k=c(s,[["render",u]]);export{g as __pageData,k as default};
